#!/usr/bin/env node
/**
 * Plate Set v1-g — self-contained materializer.
 * All 8 wall textures are embedded. No Drive, no external download.
 * After clone / in CI:  npm run plates:materialize
 * Writes apps/web/public/plates/*.jpg
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const dir = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "apps/web/public/plates"
);

const EMBEDDED = {
  "plate-01-office-01.jpg": ``,
  "plate-02a-floor-landscape-01.jpg": ``,
  "plate-02b-floor-portrait-01.jpg": ``,
  "plate-03-clinic-01.jpg": ``,
  "plate-04-board-01.jpg": ``,
  "plate-05-file-01.jpg": ``,
  "plate-06-night-01.jpg": ``,
  "plate-07-warm-ground-01.jpg": ``,

};

fs.mkdirSync(dir, { recursive: true });
let n = 0;
for (const [name, b64] of Object.entries(EMBEDDED)) {
  const buf = Buffer.from(b64.replace(/\s/g, ""), "base64");
  if (buf.length < 4 || buf[0] !== 0xff || buf[1] !== 0xd8) {
    console.error("not jpeg", name);
    process.exit(1);
  }
  fs.writeFileSync(path.join(dir, name), buf);
  console.log("wrote", name, buf.length, "bytes");
  n++;
}
console.log("Plate Set v1-g ready:", n, "files in", dir);
if (n < 8) process.exitCode = 1;
